def zero_components(a,conn=4):
 h,w=len(a),len(a[0]); seen=set(); comps=[]
 dirs=[(1,0),(-1,0),(0,1),(0,-1)]
 if conn==8: dirs += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(h):
  for c in range(w):
   if a[r][c]==0 and (r,c) not in seen:
    stack=[(r,c)];seen.add((r,c));co=set()
    while stack:
     p=stack.pop();co.add(p)
     for dr,dc in dirs:
      q=(p[0]+dr,p[1]+dc)
      if 0<=q[0]<h and 0<=q[1]<w and a[q[0]][q[1]]==0 and q not in seen: seen.add(q);stack.append(q)
    comps.append(co)
 return comps
